"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["27454"],{959187(t){t.exports=JSON.parse('{"id":7488,"title":"Git \u667A\u80FD\u5206\u6279\u63D0\u4EA4\u52A9\u624B","description":"\u5206\u6790\u5F53\u524D git \u4ED3\u5E93\u4E2D\u6240\u6709\u672A\u63D0\u4EA4\u7684\u6539\u52A8\uFF08modified\u3001staged\u3001untracked \u5168\u5305\u62EC\uFF09\uFF0C\u6309\u3010\u529F\u80FD\u76F8\u5173\u6027\u3011\u667A\u80FD\u5206\u7EC4,\u9010\u7EC4\u6267\u884C git add + git commit\u3002\\n\\n## \u5206\u7EC4\u524D\\n\u5148 `git status` + `git diff --stat`(\u5FC5\u8981\u65F6 `git diff <file>` \u770B\u5177\u4F53\u5185\u5BB9), \u9010\u6587\u4EF6\u7406\u89E3\u6539\u4E86\u4EC0\u4E48,\u518D\u51B3\u5B9A\u5206\u7EC4\u3002\\n\\n## \u5206\u7EC4\u539F\u5219\uFF08\u6838\u5FC3:\u6309\u529F\u80FD\u57DF,\u4E0D\u6309\u5355\u6B21\u6539\u52A8\u62C6\u5206\uFF09\\n1. \u7C92\u5EA6 =\u3010\u529F\u80FD\u57DF / \u5B50\u7CFB\u7EDF\u3011\u3002\u4E00\u4E2A\u529F\u80FD\u57DF\u7684\u5168\u90E8\u76F8\u5173\u6539\u52A8\u5F52\u4E3A\u3010\u4E00\u4E2A\u3011commit, \u5373\u4F7F\u91CC\u9762\u542B\u591A\u4E2A\u4FEE\u590D/\u8C03\u6574/\u5C0F\u6539\u3002\u76EE\u6807\u662F\u300C\u4E00\u4E2A\u8FDE\u8D2F\u7684\u529F\u80FD\u5355\u5143\u300D,\u7EDD\u4E0D\u62C6\u6210\u4E00\u5806\u7EC6\u788E\u539F\u5B50 commit\u3002\\n2. \u76F8\u5173\u8054\u7684\u6587\u4EF6\u540C\u7EC4:\u540C\u4E00\u529F\u80FD\u7684 \u7EC4\u4EF6 + \u6837\u5F0F + \u6D4B\u8BD5 + \u914D\u7F6E \u4E00\u8D77\u8D70\u3002\\n3. \u5206\u754C\u7EBF\u662F\u3010\u529F\u80FD/\u5B50\u7CFB\u7EDF\u3011,\u4E0D\u662F\u300C\u5355\u6B21\u6539\u52A8\u300D\u2014\u2014\u53EA\u6709\u3010\u4E0D\u540C\u529F\u80FD\u57DF\u3011\u4E4B\u95F4\u624D\u5206\u6210\u4E0D\u540C commit\u3002\\n4. \u62FF\u4E0D\u51C6\u4E24\u5757\u7B97\u4E0D\u7B97\u540C\u4E00\u529F\u80FD\u57DF \u2192 \u503E\u5411\u3010\u5408\u5E76\u3011(\u5B81\u7C97\u52FF\u788E),\u9664\u975E\u660E\u663E\u65E0\u5173\u3002\\n\\n## Commit message\uFF08Conventional Commits\uFF09\\n- \u6807\u9898:`type(scope): \u7B80\u660E\u63CF\u8FF0`(\u82F1\u6587)\u3002type \u2208 feat/fix/refactor/chore/ docs/style/perf/test;\u4E00\u7EC4\u82E5\u6DF7\u591A\u79CD\u6539\u52A8,\u53D6\u6700\u80FD\u4EE3\u8868\u672C\u7EC4\u7684\u4E3B\u5BFC type\u3002\\n- body(\u53EF\u9009):\u6709\u5FC5\u8981\u65F6\u7528\u4E2D\u6587\u6982\u62EC\u672C\u529F\u80FD\u57DF\u6539\u4E86\u4EC0\u4E48\u3001\u4E3A\u4EC0\u4E48\u3002\\n- \u3010\u4E25\u7981\u4EFB\u4F55\u6A21\u578B\u7B7E\u540D / Co-Authored-By / \u5DE5\u5177\u7F72\u540D\u3011\u3002\\n\\n## \u6267\u884C\\n\u9010\u7EC4 `git add <\u8BE5\u7EC4\u6587\u4EF6>` + `git commit`\u3002\u6BCF\u7EC4\u63D0\u4EA4\u540E\u62A5:hash \xb7 \u6807\u9898 \xb7 \u542B\u54EA\u4E9B\u6587\u4EF6\u3002\u5168\u90E8\u5B8C\u6210\u540E\u786E\u8BA4\u5269\u4F59\u672A\u63D0\u4EA4 = 0\u3002","remark":"\u628A\u672A\u63D0\u4EA4\u7684\u6539\u52A8\u6309\u3010\u529F\u80FD\u57DF\u3011\u667A\u80FD\u5206\u7EC4\uFF0C\u6279\u91CF\u63D0\u4EA4 Conventional Commits \u5165\u5E93","notes":"- \u9002\u7528\u573A\u666F:\u4E00\u6B21\u6027\u6539\u4E86\u4E00\u5806\u6587\u4EF6(\u4E00\u6574\u4E2A feature / \u4E00\u8F6E\u91CD\u6784 / \u4E00\u4E2A\u4F1A\u8BDD\u7684\u6210\u679C),\u60F3\u5E72\u51C0\u5730\u5206\u6279\u63D0\u4EA4,\u4F46\u65E2\u4E0D\u60F3\u63C9\u6210\u4E00\u4E2A\u5DE8\u578B commit,\u4E5F\u4E0D\u60F3\u62C6\u6210\u51E0\u5341\u4E2A\u539F\u5B50 commit\u2014\u2014\u8981\u7684\u662F\u300C\u4E00\u4E2A\u529F\u80FD\u57DF\u4E00\u4E2A commit\u300D\u7684\u4E2D\u95F4\u7C92\u5EA6\u3002\\n- \u6838\u5FC3\u53D6\u5411:\u523B\u610F\u4E0D\u505A\u539F\u5B50\u63D0\u4EA4\u3002\u51B3\u80DC\u89C4\u5219\u662F\u300C\u5B81\u7C97\u52FF\u788E\u300D\u2014\u2014\u62FF\u4E0D\u51C6\u5C31\u5408\u5E76\u3002\u5982\u679C\u4F60\u6070\u6070\u60F3\u8981\u7EC6\u7C92\u5EA6\u539F\u5B50 commit(\u4E00 bugfix \u4E00 commit),\u8FD9\u4E2A\u5DE5\u5177\u4E0D\u9002\u5408,\u7528\u76F8\u53CD\u53D6\u5411\u7684\u63D0\u793A\u8BCD\u3002\\n- \u8FB9\u754C:\u53EA\u5904\u7406\u3010\u672A\u63D0\u4EA4\u3011\u7684\u6539\u52A8(modified/staged/untracked),\u53EA commit\u3001\u4E0D push;\u5206\u7EC4\u9760\u8BFB diff \u51B3\u5B9A,\u6539\u52A8\u91CF\u7279\u522B\u5927\u3001\u7279\u522B\u6742\u65F6,\u5EFA\u8BAE\u63D0\u4EA4\u540E\u626B\u4E00\u773C\u5206\u7EC4\u662F\u5426\u5408\u4F60\u610F(\u5B83\u503E\u5411\u5408\u5E76,\u6781\u7AEF\u60C5\u51B5\u4E0B\u53EF\u80FD\u628A\u4E24\u4E2A\u8FB9\u7F18\u76F8\u5173\u7684\u57DF\u5E76\u5230\u4E00\u8D77)\u3002\\n- \u7EA6\u5B9A:Conventional Commits \u6807\u9898(\u82F1\u6587),\u5FC5\u8981\u65F6\u4E2D\u6587 body;\u4E0D\u5E26 Co-Authored-By / \u4EFB\u4F55\u6A21\u578B\u7F72\u540D(\u6309\u9700\u6C42\u5185\u7F6E)\u3002","owner":"test","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-06-08T11:35:05.159Z"}')}}]);